import{_ as o,o as t,c as d,ag as r}from"./chunks/framework.DQQHyi2x.js";const g=JSON.parse('{"title":"Agent Bridge — Platform selection (Anthropic / Bedrock)","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-29-agent-bridge-bedrock-platform-design.md","filePath":"superpowers/specs/2026-05-29-agent-bridge-bedrock-platform-design.md"}'),n={name:"superpowers/specs/2026-05-29-agent-bridge-bedrock-platform-design.md"};function a(i,e,s,c,l,p){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="agent-bridge-—-platform-selection-anthropic-bedrock" tabindex="-1">Agent Bridge — Platform selection (Anthropic / Bedrock) <a class="header-anchor" href="#agent-bridge-—-platform-selection-anthropic-bedrock" aria-label="Permalink to &quot;Agent Bridge — Platform selection (Anthropic / Bedrock)&quot;">​</a></h1><p><strong>Date:</strong> 2026-05-29 <strong>Status:</strong> Design — pending implementation <strong>Scope:</strong> Add a per-session platform picker (Anthropic default / Amazon Bedrock) to the Agent Bridge &quot;New Session&quot; dialog for the Claude Code provider, injecting the appropriate Bedrock environment variables into the spawned <code>claude</code> process.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>The Agent Bridge spawns <code>claude</code> inside a tmux session (<code>backend/app/services/agent_bridge/spawn.py</code>). Today it calls <code>tmux new-session</code> <strong>without passing any environment</strong>, so the session simply inherits the backend server&#39;s environment. There is no way, from the UI, to start a session against Amazon Bedrock rather than the default Anthropic API. Running Claude Code against Bedrock requires setting <code>CLAUDE_CODE_USE_BEDROCK=1</code> plus AWS configuration (region, optionally profile and model) in the process environment.</p><p>The user wants to select <strong>Bedrock vs. Anthropic</strong> when starting an Agent Bridge session.</p><h2 id="decisions-locked" tabindex="-1">Decisions (locked) <a class="header-anchor" href="#decisions-locked" aria-label="Permalink to &quot;Decisions (locked)&quot;">​</a></h2><ul><li><strong>Credential source: inherit from the server.</strong> Claude Deck never collects or stores AWS secrets. Selecting Bedrock sets non-secret env vars (<code>CLAUDE_CODE_USE_BEDROCK</code>, region, profile name, model ID) and lets the AWS SDK credential chain on the backend host resolve actual credentials (env vars, <code>~/.aws/credentials</code> profile, or instance role).</li><li><strong>Bedrock fields exposed:</strong> AWS Region, AWS Profile name, Model ARN/ID. All optional.</li><li><strong>Vertex:</strong> out of scope for now. The design leaves the door open via a single env-builder map so Vertex can be added later without reworking the plumbing.</li><li><strong>Remember last selection:</strong> yes — persist the last-used platform and its (non-secret) field values in browser <code>localStorage</code> so the dialog pre-fills next time. No backend persistence change.</li></ul><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><p>A <code>platform</code> enum plus a provider-side env builder.</p><ol><li>The dialog gains a <strong>Platform</strong> selector for the Claude Code provider: <code>Anthropic</code> (default) or <code>Amazon Bedrock</code>.</li><li>Selecting Bedrock reveals three optional inputs: <strong>AWS Region</strong>, <strong>AWS Profile</strong>, <strong>Model ARN/ID</strong>.</li><li>On spawn, the backend translates the platform choice into a <code>dict[str, str]</code> of environment variables and injects them into the tmux session via <code>tmux new-session -e KEY=VALUE</code> (one <code>-e</code> per variable).</li><li><code>Anthropic</code> produces an <strong>empty</strong> env map → the tmux command is byte-for-byte identical to today (full backward compatibility).</li></ol><h3 id="env-mapping-bedrock" tabindex="-1">Env mapping (Bedrock) <a class="header-anchor" href="#env-mapping-bedrock" aria-label="Permalink to &quot;Env mapping (Bedrock)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Env var</th><th>Condition</th></tr></thead><tbody><tr><td>(platform = bedrock)</td><td><code>CLAUDE_CODE_USE_BEDROCK=1</code></td><td>always when Bedrock</td></tr><tr><td>AWS Region</td><td><code>AWS_REGION=&lt;value&gt;</code></td><td>if provided</td></tr><tr><td>AWS Profile</td><td><code>AWS_PROFILE=&lt;value&gt;</code></td><td>if provided</td></tr><tr><td>Model ARN/ID</td><td><code>ANTHROPIC_MODEL=&lt;value&gt;</code></td><td>if provided</td></tr></tbody></table><h3 id="alternatives-considered-rejected" tabindex="-1">Alternatives considered (rejected) <a class="header-anchor" href="#alternatives-considered-rejected" aria-label="Permalink to &quot;Alternatives considered (rejected)&quot;">​</a></h3><ul><li><strong>settings.json <code>env</code> only</strong> — Claude Code already reads <code>env</code> from settings.json, so Bedrock vars could be set globally there with zero code. Rejected: it is global, not the per-session picker requested, and the spawn path never sets a custom env anyway.</li><li><strong>Store AWS keys in Claude Deck</strong> (typed per session, or saved profiles) — rejected in favor of inherit-from-server, which is safer (no secret storage) and simpler.</li></ul><h2 id="components-data-flow" tabindex="-1">Components &amp; data flow <a class="header-anchor" href="#components-data-flow" aria-label="Permalink to &quot;Components &amp; data flow&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li><p><strong><code>backend/app/services/providers/platform_env.py</code> (new)</strong></p><ul><li>Constants: <code>PLATFORM_ANTHROPIC = &quot;anthropic&quot;</code>, <code>PLATFORM_BEDROCK = &quot;bedrock&quot;</code>.</li><li><code>build_platform_env(platform, region, aws_profile, model) -&gt; dict[str, str]</code>: <ul><li>Anthropic → <code>{}</code>.</li><li>Bedrock → <code>{&quot;CLAUDE_CODE_USE_BEDROCK&quot;: &quot;1&quot;, ...}</code> adding region/profile/model only when set.</li><li>Defensive validation: reject values containing <code>\\n</code> or <code>\\0</code>; skip empty/whitespace-only values.</li></ul></li><li>Single extension point for a future Vertex platform.</li></ul></li><li><p><strong><code>backend/app/services/providers/base.py</code></strong> — add four frozen-dataclass fields to <code>SpawnCommandOptions</code>: <code>platform: str = &quot;anthropic&quot;</code>, <code>aws_region: str | None = None</code>, <code>aws_profile: str | None = None</code>, <code>bedrock_model: str | None = None</code>. A distinct <code>bedrock_model</code> (not the existing Codex-only <code>model</code>) avoids overloading semantics and keeps the Anthropic Claude Code spawn untouched.</p></li><li><p><strong><code>backend/app/services/agent_bridge/spawn.py</code></strong> — in <code>spawn_session</code>:</p><ul><li>Call <code>build_platform_env(...)</code> from the options.</li><li>Insert <code>-e KEY=VALUE</code> argv elements into the <code>tmux new-session</code> call (after <code>-c &lt;dir&gt;</code>, before the shell command, so the fixed <code>-d -s &lt;name&gt; -c &lt;dir&gt;</code> prefix is unchanged). Empty env → unchanged command.</li><li>Store <code>platform</code> in <code>_spawned_sessions[name]</code> metadata for visibility. Never log AWS values.</li></ul></li><li><p><strong><code>backend/app/api/v1/agent_bridge/router.py</code></strong> — add the four fields to <code>SpawnRequest</code> and pass them through when constructing <code>SpawnCommandOptions</code>.</p></li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li><strong><code>frontend/src/features/cc-bridge/types.ts</code></strong> — add <code>platform?</code>, <code>aws_region?</code>, <code>aws_profile?</code>, <code>bedrock_model?</code> to <code>SpawnSessionRequest</code>.</li><li><strong><code>frontend/src/features/cc-bridge/NewSessionDialog.tsx</code></strong> — for the Claude Code provider: <ul><li>A <strong>Platform</strong> <code>&lt;Select&gt;</code> (Anthropic / Amazon Bedrock), defaulting to Anthropic.</li><li>When Bedrock is selected, conditionally render Region / Profile / Model inputs (mirroring the existing Codex-only conditional fields), with a hint that region is usually required.</li><li><strong>Remember last selection:</strong> read/write <code>localStorage</code> (e.g. key <code>cc-bridge.platform</code>) holding <code>{platform, aws_region, aws_profile, bedrock_model}</code> — <strong>non-secret values only</strong> — to pre-fill on open.</li></ul></li></ul><h3 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h3><p>Dialog → <code>SpawnSessionRequest</code> (with platform fields) → <code>POST</code> spawn → <code>SpawnRequest</code> → <code>SpawnCommandOptions</code> → <code>spawn_session</code> → <code>build_platform_env</code> → <code>tmux new-session -e ...</code> → <code>claude</code> runs in a tmux session whose environment carries the Bedrock vars; the AWS SDK resolves credentials from the inherited chain.</p><h2 id="error-handling-validation" tabindex="-1">Error handling &amp; validation <a class="header-anchor" href="#error-handling-validation" aria-label="Permalink to &quot;Error handling &amp; validation&quot;">​</a></h2><ul><li><strong>Injection safety:</strong> values are passed as separate argv elements to <code>tmux -e KEY=VALUE</code>, never shell-interpolated, so there is no quoting/injection risk. <code>build_platform_env</code> additionally rejects values with <code>\\n</code>/<code>\\0</code>.</li><li><strong>Optional fields:</strong> Region/profile/model are optional even for Bedrock. Bedrock with no region sets only <code>CLAUDE_CODE_USE_BEDROCK=1</code>; Claude Code / the AWS SDK surface their own &quot;no region&quot; error inside the tmux session. We do not duplicate AWS-side validation client-side.</li><li><strong>No credential handling</strong> in the path — nothing to leak, log, or persist. Logs record <code>platform=bedrock</code> but no AWS values.</li><li><strong>Backward compatibility:</strong> omitting <code>platform</code> defaults to <code>&quot;anthropic&quot;</code>; Anthropic yields an empty env map and the current tmux command.</li></ul><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li><strong>Backend (pytest):</strong><ul><li><code>build_platform_env</code>: Anthropic → <code>{}</code>; Bedrock with all fields; Bedrock with only region; defensive rejection of <code>\\n</code>/<code>\\0</code> and empty values.</li><li><code>spawn_session</code>: mock <code>subprocess.run</code>; assert <code>-e</code> flags appear in the tmux argv for Bedrock, and that Anthropic produces no <code>-e</code> flags.</li></ul></li><li><strong>Frontend:</strong> no test harness exists yet (per CLAUDE.md); rely on <code>tsc</code> + ESLint and manual verification.</li><li><strong>Manual:</strong> Anthropic session unchanged; Bedrock session on an AWS-credentialed host starts on Bedrock; dialog pre-fills the last selection.</li></ul><h2 id="out-of-scope-yagni" tabindex="-1">Out of scope (YAGNI) <a class="header-anchor" href="#out-of-scope-yagni" aria-label="Permalink to &quot;Out of scope (YAGNI)&quot;">​</a></h2><ul><li>Google Vertex AI (door left open via the env-builder map).</li><li>Storing AWS secrets or named credential profiles in Claude Deck.</li><li>Database persistence of bridge sessions (they remain in-memory).</li><li>Editing settings.json from this feature.</li></ul><h2 id="files-to-change" tabindex="-1">Files to change <a class="header-anchor" href="#files-to-change" aria-label="Permalink to &quot;Files to change&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>backend/app/services/providers/platform_env.py</code></td><td><strong>New</strong> — platform constants + <code>build_platform_env()</code></td></tr><tr><td><code>backend/app/services/providers/base.py</code></td><td>+4 fields on <code>SpawnCommandOptions</code></td></tr><tr><td><code>backend/app/services/agent_bridge/spawn.py</code></td><td>Build env, inject <code>-e</code> flags, store <code>platform</code> metadata</td></tr><tr><td><code>backend/app/api/v1/agent_bridge/router.py</code></td><td>+4 fields on <code>SpawnRequest</code>, pass through</td></tr><tr><td><code>backend/tests/</code></td><td>New tests for env builder + spawn argv</td></tr><tr><td><code>frontend/src/features/cc-bridge/types.ts</code></td><td>+4 fields on <code>SpawnSessionRequest</code></td></tr><tr><td><code>frontend/src/features/cc-bridge/NewSessionDialog.tsx</code></td><td>Platform select + conditional Bedrock fields + localStorage remember</td></tr></tbody></table><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>Feature → GitHub issue + <code>feat/agent-bridge-bedrock-platform</code> branch + PR against <code>master</code>.</p>',31)])])}const u=o(n,[["render",a]]);export{g as __pageData,u as default};
